//! Known-answer and refusal tests for the transparency log's v3 account index
//! (`signet_crypto::vrf`, ECVRF-RISTRETTO255-SHA512 via the pinned `vrf-r255`).
//!
//! Two kinds of vector, kept apart on purpose:
//! - the **C2SP spec vector** (c2sp.org/vrf-r255), run through the crate's own
//!   API: it proves the crate in our lock reproduces the published suite;
//! - a **golden vector of our framing** (the alpha domain + account id): it was
//!   generated by this code, so it guards stability, not correctness. Its
//!   correctness rests on the spec vector plus the framing test below.

use signet_crypto::error::CryptoError;
use signet_crypto::vrf::{self, VrfSecretKey};

const TV_SK: &str = "3431c2b03533e280b23232e280b34e2c3132c2b03238e280b23131e280b34500";
const TV_PK: &str = "54136cd90d99fbd1d4e855d9556efea87ba0337f2a6ce22028d0f5726fcb854e";
const TV_ALPHA: &str = "633273702e6f72672f7672662d72323535";
const TV_PI: &str = "0a97d961262fb549b4175c5117860f42ae44a123f93c476c439eddd1c0cff9265c805525233e2284dbed45e593b8eea31d5ca9734d72bcbba9738d5237f955f3b2422351149d1312503b6441a47c940c";
const TV_BETA: &str = "dd653f0879b48c3ef69e13551239bec4cbcc1c18fe8894de2e9e1c790e18273603bf1c6c25d7a797aeff3c43fd32b974d3fcbd4bcce916007097922a3ea3a794";

/// `00000000-0000-4000-8000-000000000001` (Cat 07 HUMAN_1) raw 16 bytes.
const HUMAN_1: [u8; 16] = [
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x00, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01,
];
/// `00000000-0000-4000-8000-000000000002`.
const HUMAN_2: [u8; 16] = [
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x00, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02,
];

fn h<const N: usize>(s: &str) -> [u8; N] {
    hex::decode(s).unwrap().try_into().unwrap()
}

fn tv_key() -> VrfSecretKey {
    VrfSecretKey::from_bytes(&h::<32>(TV_SK)).unwrap()
}

#[test]
fn the_pinned_crate_reproduces_the_c2sp_spec_vector() {
    let sk = vrf_r255::SecretKey::from_bytes(h::<32>(TV_SK)).unwrap();
    let pk = vrf_r255::PublicKey::from_bytes(h::<32>(TV_PK)).unwrap();
    assert_eq!(vrf_r255::PublicKey::from(sk), pk);
    let alpha = hex::decode(TV_ALPHA).unwrap();
    let pi = vrf_r255::Proof::from_bytes(h::<80>(TV_PI)).unwrap();
    assert_eq!(sk.prove(&alpha), pi);
    assert_eq!(pk.verify(&alpha, &pi).unwrap(), h::<64>(TV_BETA));
}

#[test]
fn our_key_loading_derives_the_spec_public_key() {
    assert_eq!(tv_key().public_key(), h::<32>(TV_PK));
}

#[test]
fn alpha_is_the_domain_a_zero_byte_and_the_raw_account_id() {
    let mut expected = b"signet-pubkey-log-v3-account-index".to_vec();
    expected.push(0x00);
    expected.extend_from_slice(&HUMAN_1);
    assert_eq!(vrf::alpha(&HUMAN_1), expected);
    assert_eq!(vrf::ALPHA_DOMAIN, b"signet-pubkey-log-v3-account-index");
    assert_eq!(vrf::VRF_SUITE, "ECVRF-RISTRETTO255-SHA512");
}

#[test]
fn golden_vector_of_our_framing() {
    let (index, proof) = tv_key().prove(&HUMAN_1).unwrap();
    assert_eq!(
        hex::encode(index),
        "0c4270a3d2be444bad692c4905589febd1e2e1b4d1fa27f4a35f7ac32407a0b8a2dfaa8ba5465328f91dd997759cb341bb8a78995b25dbbfae2bce0efaf9ecd0"
    );
    assert_eq!(
        hex::encode(proof),
        "14be56b17384f56aa2789a32cd2eaed3edbcc1caa1a23bb4adac1dd45c59ab7e552dcdb321dcddccbf1193c32671382e06eee3168bc8c1126b39cf1cd31e1a89d912468f20b58dfe7280e0667fbcfa06"
    );
}

#[test]
fn prove_then_verify_returns_the_same_index_and_is_deterministic() {
    let sk = tv_key();
    let (index, proof) = sk.prove(&HUMAN_1).unwrap();
    assert_eq!(
        vrf::verify(&sk.public_key(), &HUMAN_1, &proof).unwrap(),
        index
    );
    assert_eq!(sk.prove(&HUMAN_1).unwrap(), (index, proof));
    assert_eq!(index.len(), vrf::INDEX_LEN);
}

#[test]
fn the_index_is_the_whole_64_byte_output_never_a_truncation() {
    let sk = tv_key();
    let (index, proof) = sk.prove(&HUMAN_1).unwrap();
    let raw = vrf_r255::PublicKey::from_bytes(sk.public_key())
        .unwrap()
        .verify(
            &vrf::alpha(&HUMAN_1),
            &vrf_r255::Proof::from_bytes(proof).unwrap(),
        )
        .unwrap();
    assert_eq!(index, raw);
}

#[test]
fn a_proof_for_one_account_is_refused_for_another() {
    let sk = tv_key();
    let (_, proof) = sk.prove(&HUMAN_1).unwrap();
    assert_eq!(
        vrf::verify(&sk.public_key(), &HUMAN_2, &proof),
        Err(CryptoError::SignatureInvalid)
    );
}

#[test]
fn a_proof_under_one_key_is_refused_under_another() {
    let (_, proof) = tv_key().prove(&HUMAN_1).unwrap();
    let other = VrfSecretKey::generate();
    assert_eq!(
        vrf::verify(&other.public_key(), &HUMAN_1, &proof),
        Err(CryptoError::SignatureInvalid)
    );
}

#[test]
fn every_altered_proof_byte_is_refused() {
    let sk = tv_key();
    let (_, proof) = sk.prove(&HUMAN_1).unwrap();
    for i in 0..vrf::PROOF_LEN {
        let mut bad = proof;
        bad[i] ^= 0x01;
        assert!(
            vrf::verify(&sk.public_key(), &HUMAN_1, &bad).is_err(),
            "altered proof byte {i} was accepted"
        );
    }
}

#[test]
fn distinct_accounts_and_distinct_keys_give_distinct_indices() {
    let sk = tv_key();
    let (a, _) = sk.prove(&HUMAN_1).unwrap();
    let (b, _) = sk.prove(&HUMAN_2).unwrap();
    let (c, _) = VrfSecretKey::generate().prove(&HUMAN_1).unwrap();
    assert_ne!(a, b);
    assert_ne!(a, c);
}

#[test]
fn degenerate_keys_are_refused() {
    // The zero scalar (its public key is the identity) and a non-canonical scalar.
    assert_eq!(
        VrfSecretKey::from_bytes(&[0u8; 32]).unwrap_err(),
        CryptoError::InvalidInput("VRF secret key")
    );
    assert!(VrfSecretKey::from_bytes(&[0xffu8; 32]).is_err());
    // The identity point as a public key.
    let (_, proof) = tv_key().prove(&HUMAN_1).unwrap();
    assert_eq!(
        vrf::verify(&[0u8; 32], &HUMAN_1, &proof),
        Err(CryptoError::InvalidInput("VRF public key"))
    );
}

#[test]
fn debug_never_prints_the_secret() {
    let sk = tv_key();
    let shown = format!("{sk:?}");
    assert!(
        !shown.contains(TV_SK),
        "Debug printed the secret scalar: {shown}"
    );
    assert!(
        shown.contains(TV_PK),
        "Debug should name the public key: {shown}"
    );
}

#[test]
fn the_secret_round_trips_through_its_storage_bytes() {
    let sk = VrfSecretKey::generate();
    let back = VrfSecretKey::from_bytes(&sk.to_bytes()).unwrap();
    assert_eq!(back.public_key(), sk.public_key());
    assert_eq!(back.prove(&HUMAN_1).unwrap(), sk.prove(&HUMAN_1).unwrap());
}
